<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; admin_requerido(); $error='';$editar=null;
if($_SERVER['REQUEST_METHOD']==='POST'){validar_csrf();try{$accion=$_POST['accion']??'';if($accion==='guardar'){$id=(int)($_POST['id']??0);$equipo=(int)($_POST['equipo_id']??0);$nombres=trim($_POST['nombres']??'');$apellidos=trim($_POST['apellidos']??'');$dorsal=($_POST['dorsal']??'')!==''?(int)$_POST['dorsal']:null;$posicion=trim($_POST['posicion']??'');if(!$equipo||$nombres===''||$apellidos==='')throw new RuntimeException('Selecciona un equipo e indica nombres y apellidos.');if($dorsal!==null&&($dorsal<0||$dorsal>99))throw new RuntimeException('El dorsal debe estar entre 0 y 99.');if($id){$s=$pdo->prepare('UPDATE jugadores SET equipo_id=?,nombres=?,apellidos=?,dorsal=?,posicion=? WHERE id=?');$s->execute([$equipo,$nombres,$apellidos,$dorsal,$posicion?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO jugadores(equipo_id,nombres,apellidos,dorsal,posicion) VALUES(?,?,?,?,?)');$s->execute([$equipo,$nombres,$apellidos,$dorsal,$posicion?:null]);}header('Location: jugadores.php?ok=1');exit;}elseif($accion==='eliminar'){$s=$pdo->prepare('DELETE FROM jugadores WHERE id=?');$s->execute([(int)$_POST['id']]);header('Location: jugadores.php?eliminado=1');exit;}}catch(Throwable $ex){$error=$ex instanceof PDOException?'No se pudo guardar. Comprueba que el dorsal no esté repetido dentro del equipo.':$ex->getMessage();}}
if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM jugadores WHERE id=?');$s->execute([(int)$_GET['editar']]);$editar=$s->fetch();}$equipos=$pdo->query('SELECT id,nombre FROM equipos ORDER BY nombre')->fetchAll();$jugadores=$pdo->query('SELECT j.*,e.nombre AS equipo_nombre FROM jugadores j JOIN equipos e ON e.id=j.equipo_id ORDER BY e.nombre,j.apellidos,j.nombres')->fetchAll();$pageTitle='Gestionar jugadores';require __DIR__.'/../src/header.php';?>
<section class="page-intro"><span class="eyebrow">ADMINISTRACIÓN</span><h1>Jugadores</h1><p>Registra jugadores y asígnalos a un equipo.</p></section><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert alert-success">Jugador guardado correctamente.</div><?php endif;?><?php if(isset($_GET['eliminado'])):?><div class="alert alert-success">Jugador eliminado.</div><?php endif;?>
<?php if(!$equipos):?><div class="alert alert-error">Primero registra al menos un equipo en el módulo Equipos.</div><?php endif;?><div class="admin-two-col"><form class="form-card" method="post"><h2><?=$editar?'Editar jugador':'Registrar jugador'?></h2><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?=(int)($editar['id']??0)?>"><label>Equipo *<select name="equipo_id" required><option value="">Seleccionar equipo</option><?php foreach($equipos as $eq):?><option value="<?=(int)$eq['id']?>" <?=((int)($editar['equipo_id']??0)===(int)$eq['id'])?'selected':''?>><?=e($eq['nombre'])?></option><?php endforeach;?></select></label><label>Nombres *<input name="nombres" required maxlength="100" value="<?=e($editar['nombres']??'')?>"></label><label>Apellidos *<input name="apellidos" required maxlength="100" value="<?=e($editar['apellidos']??'')?>"></label><label>Dorsal (0–99)<input type="number" min="0" max="99" name="dorsal" value="<?=e($editar['dorsal']??'')?>"></label><label>Posición<select name="posicion"><option value="">Seleccionar</option><?php foreach(['Base','Escolta','Alero','Ala-pívot','Pívot'] as $pos):?><option <?=($editar['posicion']??'')===$pos?'selected':''?>><?=e($pos)?></option><?php endforeach;?></select></label><button class="btn" type="submit" <?=!$equipos?'disabled':''?>>Guardar jugador</button><?php if($editar):?><a class="back-link" href="jugadores.php">Cancelar edición</a><?php endif;?></form><section><h2 class="list-title">Jugadores registrados (<?=count($jugadores)?>)</h2><?php if(!$jugadores):?><div class="empty-state">No hay jugadores registrados.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Jugador</th><th>Equipo</th><th>Dorsal</th><th>Acciones</th></tr></thead><tbody><?php foreach($jugadores as $j):?><tr><td><strong><?=e($j['nombres'].' '.$j['apellidos'])?></strong><small class="table-sub"><?=e($j['posicion']?:'Posición no indicada')?></small></td><td><?=e($j['equipo_nombre'])?></td><td><?=e($j['dorsal']??'—')?></td><td class="actions-cell"><a href="?editar=<?=(int)$j['id']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este jugador?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=(int)$j['id']?>"><button class="link-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php require __DIR__.'/../src/footer.php';?>